static inline GcOp gc_decode(uint32_t insn) {
  switch (insn >> 26) {
  case 0x03:
    return GC_OP_TWI;
  case 0x04:
    return (GcOp)gc_decode_table_04[insn & 0x7ffu];
  case 0x07:
    return GC_OP_MULLI;
  case 0x08:
    return GC_OP_SUBFIC;
  case 0x0a:
    return GC_OP_CMPLI;
  case 0x0b:
    return GC_OP_CMPI;
  case 0x0c:
    return GC_OP_ADDIC;
  case 0x0d:
    return GC_OP_ADDIC_;
  case 0x0e:
    return GC_OP_ADDI;
  case 0x0f:
    return GC_OP_ADDIS;
  case 0x10:
    return GC_OP_BC;
  case 0x11:
    if ((insn & 0x7ffu) == 0x002u) return GC_OP_SC;
    return GC_OP_ILLEGAL;
  case 0x12:
    return GC_OP_B;
  case 0x13:
    return (GcOp)gc_decode_table_13[insn & 0x7ffu];
  case 0x14:
    return GC_OP_RLWIMI;
  case 0x15:
    return GC_OP_RLWINM;
  case 0x17:
    return GC_OP_RLWNM;
  case 0x18:
    return GC_OP_ORI;
  case 0x19:
    return GC_OP_ORIS;
  case 0x1a:
    return GC_OP_XORI;
  case 0x1b:
    return GC_OP_XORIS;
  case 0x1c:
    return GC_OP_ANDI_;
  case 0x1d:
    return GC_OP_ANDIS_;
  case 0x1f:
    return (GcOp)gc_decode_table_1f[insn & 0x7ffu];
  case 0x20:
    return GC_OP_LWZ;
  case 0x21:
    return GC_OP_LWZU;
  case 0x22:
    return GC_OP_LBZ;
  case 0x23:
    return GC_OP_LBZU;
  case 0x24:
    return GC_OP_STW;
  case 0x25:
    return GC_OP_STWU;
  case 0x26:
    return GC_OP_STB;
  case 0x27:
    return GC_OP_STBU;
  case 0x28:
    return GC_OP_LHZ;
  case 0x29:
    return GC_OP_LHZU;
  case 0x2a:
    return GC_OP_LHA;
  case 0x2b:
    return GC_OP_LHAU;
  case 0x2c:
    return GC_OP_STH;
  case 0x2d:
    return GC_OP_STHU;
  case 0x2e:
    return GC_OP_LMW;
  case 0x2f:
    return GC_OP_STMW;
  case 0x30:
    return GC_OP_LFS;
  case 0x31:
    return GC_OP_LFSU;
  case 0x32:
    return GC_OP_LFD;
  case 0x33:
    return GC_OP_LFDU;
  case 0x34:
    return GC_OP_STFS;
  case 0x35:
    return GC_OP_STFSU;
  case 0x36:
    return GC_OP_STFD;
  case 0x37:
    return GC_OP_STFDU;
  case 0x38:
    return GC_OP_PSQ_L;
  case 0x39:
    return GC_OP_PSQ_LU;
  case 0x3b:
    return (GcOp)gc_decode_table_3b[insn & 0x7ffu];
  case 0x3c:
    return GC_OP_PSQ_ST;
  case 0x3d:
    return GC_OP_PSQ_STU;
  case 0x3f:
    return (GcOp)gc_decode_table_3f[insn & 0x7ffu];
  default:
    return GC_OP_ILLEGAL;
  }
}

/* True when every bit the encoding fixes really holds its fixed value.
 * A canonical encoding is what an assembler emits; a non-canonical one
 * still executes, but it is a good signal that the analyzer has wandered
 * into data. */
static inline int gc_decode_is_canonical(GcOp op, uint32_t insn) {
  const GcOpInfo *info = &gc_op_info[op];
  return op != GC_OP_ILLEGAL && (insn & info->bitmask) == info->pattern;
}

